from AlgorithmImports import *
from datetime import datetime, timedelta


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):

    def initialize(self) -> None:
        self.set_time_zone(TimeZones.NEW_YORK)
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)

        self._spy = self.add_equity(
            "SPY",
            Resolution.MINUTE,
            data_normalization_mode=DataNormalizationMode.RAW
        ).symbol

        option = self.add_option("SPY", Resolution.MINUTE)
        self._option_symbol = option.symbol

        # Includes weekly expirations and a deliberately broad strike/expiry range.
        option.set_filter(
            lambda universe: universe.include_weeklys()
                .strikes(-1000, 1000)
                .expiration(timedelta(days=0), timedelta(days=365))
        )

        self._fast = SimpleMovingAverage(5)
        self._slow = SimpleMovingAverage(20)

        self._five_minute_consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self._five_minute_consolidator.data_consolidated += self._on_five_minute_bar
        self.subscription_manager.add_consolidator(
            self._spy, self._five_minute_consolidator
        )

        self._entry_ticket = None
        self._exit_ticket = None
        self._held_contract = None
        self._held_expiry = None
        self._entry_fill_price = None
        self._blocked_entry_date = None

        self._spy_exchange_hours = self.securities[self._spy].exchange.hours

    def on_data(self, slice: Slice) -> None:
        self._liquidate_unexpected_spy_position()

        if self._held_contract is not None:
            quantity = self.portfolio[self._held_contract].quantity

            if quantity == 0 and not self._is_open(self._exit_ticket):
                self._clear_option_position_state()
            else:
                # Do not intentionally carry an option into its expiration date.
                if self.time.date() >= self._held_expiry:
                    self._blocked_entry_date = self.time.date()
                    self._submit_exit("expiration processing")
                    return

                if self._is_pre_expiration_time_stop():
                    self._submit_exit("15:45 pre-expiration time stop")
                    return

                self._check_profit_target(slice)

    def _on_five_minute_bar(self, bar: TradeBar) -> None:
        # Save values from the preceding completed five-minute bar.
        prior_ready = self._fast.is_ready and self._slow.is_ready
        prior_fast = self._fast.current.value if prior_ready else None
        prior_slow = self._slow.current.value if prior_ready else None

        # A consolidator only emits actual consolidated bars; no gap is filled here.
        self._fast.update(bar.end_time, bar.close)
        self._slow.update(bar.end_time, bar.close)

        if not (prior_ready and self._fast.is_ready and self._slow.is_ready):
            return

        bullish_cross = (
            prior_fast <= prior_slow
            and self._fast.current.value > self._slow.current.value
        )
        if not bullish_cross:
            return

        end_time = bar.end_time
        if not (
            end_time.hour > 9 or (end_time.hour == 9 and end_time.minute >= 45)
        ):
            return
        if end_time.hour > 14 or (end_time.hour == 14 and end_time.minute > 30):
            return

        if self._blocked_entry_date == self.time.date():
            return

        if (
            self._held_contract is not None
            or self._is_open(self._entry_ticket)
            or self._is_open(self._exit_ticket)
        ):
            return

        # The consolidator callback runs on the current data Slice.
        self._try_enter_from_current_slice(self.current_slice, bar.close)

    def _try_enter_from_current_slice(self, slice: Slice, spy_price: float) -> None:
        chain = slice.option_chains.get(self._option_symbol)
        if not chain:
            self.debug(f"{self.time}: entry skipped - no SPY option chain")
            return

        today = self.time.date()
        contracts = list(chain)

        valid_expiries = sorted({
            contract.expiry.date()
            for contract in contracts
            if (contract.expiry.date() - today).days >= 7
        })

        if not valid_expiries:
            self.debug(f"{self.time}: entry skipped - no expiry at least 7 calendar days away")
            return

        selected_expiry = valid_expiries[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in contracts
            if contract.expiry.date() == selected_expiry
            and contract.right == OptionRight.CALL
            and contract.strike >= minimum_strike
        ]

        if not candidates:
            self.debug(
                f"{self.time}: entry skipped - no qualifying call for {selected_expiry}"
            )
            return

        selected = min(candidates, key=lambda c: (c.strike, str(c.symbol)))
        self._entry_ticket = self.market_order(selected.symbol, 1)

        self.debug(
            f"{self.time}: submitted entry for {selected.symbol}, "
            f"expiry {selected_expiry}, strike {selected.strike}"
        )

    def _check_profit_target(self, slice: Slice) -> None:
        if self._entry_fill_price is None or self._is_open(self._exit_ticket):
            return

        chain = slice.option_chains.get(self._option_symbol)
        if not chain:
            return

        contract = next(
            (c for c in chain if c.symbol == self._held_contract),
            None
        )
        if contract is None:
            return

        bid = contract.bid_price
        ask = contract.ask_price
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self._entry_fill_price:
            self._submit_exit(
                f"50% profit target at midpoint {midpoint:.2f}"
            )

    def _is_pre_expiration_time_stop(self) -> bool:
        if self.time.hour != 15 or self.time.minute != 45:
            return False

        previous_trading_day = self._spy_exchange_hours.get_previous_trading_day(
            datetime.combine(self._held_expiry, datetime.min.time())
        ).date()

        return self.time.date() == previous_trading_day

    def _submit_exit(self, reason: str) -> None:
        if self._held_contract is None or self._is_open(self._exit_ticket):
            return

        quantity = self.portfolio[self._held_contract].quantity
        if quantity == 0:
            self._clear_option_position_state()
            return

        self._exit_ticket = self.market_order(self._held_contract, -quantity)
        self.debug(f"{self.time}: submitted exit for {self._held_contract} - {reason}")

    def on_order_event(self, order_event: OrderEvent) -> None:
        if self._entry_ticket is not None and order_event.order_id == self._entry_ticket.order_id:
            if order_event.status == OrderStatus.FILLED:
                self._held_contract = order_event.symbol
                self._held_expiry = order_event.symbol.id.date.date()
                self._entry_fill_price = order_event.fill_price
                self._entry_ticket = None
                self.debug(
                    f"{self.time}: entry filled for {order_event.symbol} "
                    f"at {order_event.fill_price:.2f}"
                )
            elif order_event.status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                self.debug(f"{self.time}: entry order did not complete")
                self._entry_ticket = None

        if self._exit_ticket is not None and order_event.order_id == self._exit_ticket.order_id:
            if order_event.status == OrderStatus.FILLED:
                self.debug(
                    f"{self.time}: exit filled for {order_event.symbol} "
                    f"at {order_event.fill_price:.2f}"
                )
                self._exit_ticket = None
                if self.portfolio[order_event.symbol].quantity == 0:
                    self._clear_option_position_state()
            elif order_event.status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                self._exit_ticket = None

    def on_assignment_order_event(self, order_event: OrderEvent) -> None:
        self.debug(f"{self.time}: unexpected option assignment/exercise event")
        self._clear_option_position_state()
        self._liquidate_unexpected_spy_position()

    def _liquidate_unexpected_spy_position(self) -> None:
        quantity = self.portfolio[self._spy].quantity
        if quantity != 0:
            self.debug(
                f"{self.time}: unexpected SPY equity position ({quantity}); liquidating"
            )
            self.market_order(self._spy, -quantity)

    @staticmethod
    def _is_open(ticket) -> bool:
        return ticket is not None and ticket.status not in (
            OrderStatus.FILLED,
            OrderStatus.CANCELED,
            OrderStatus.INVALID
        )

    def _clear_option_position_state(self) -> None:
        self._held_contract = None
        self._held_expiry = None
        self._entry_fill_price = None
        self._exit_ticket = None
