from AlgorithmImports import *
from collections import deque
from datetime import timedelta, time


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def initialize(self):
        self.set_time_zone(TimeZones.NEW_YORK)
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)

        self.spy = self.add_equity(
            "SPY",
            Resolution.MINUTE,
            data_normalization_mode=DataNormalizationMode.RAW
        ).symbol

        option = self.add_option("SPY", Resolution.MINUTE)
        option.set_filter(
            lambda universe: universe.include_weeklys()
            .strikes(-200, 200)
            .expiration(0, 180)
        )
        self.option_symbol = option.symbol

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.current_five_minute_end = None
        self.expected_minute_end = None
        self.five_minute_closes = []

        self.held_contract = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.pending_entry_symbol = None
        self.pending_exit_symbol = None
        self.blocked_entry_date = None

        self.schedule.on(
            self.date_rules.every_day(self.spy),
            self.time_rules.at(15, 45),
            self._pre_expiry_time_stop
        )

    def on_data(self, data: Slice):
        self._liquidate_unexpected_spy_position()
        self._expiration_safety_exit()
        self._check_profit_target(data)
        self._process_spy_minute(data)

    def _process_spy_minute(self, data: Slice):
        bar = data.bars.get(self.spy)
        if bar is None:
            return

        minute_end = bar.end_time
        session_start = time(9, 31)
        session_end = time(16, 0)

        if minute_end.time() < session_start or minute_end.time() > session_end:
            self.current_five_minute_end = None
            self.expected_minute_end = None
            self.five_minute_closes = []
            return

        rounded_end = minute_end.replace(second=0, microsecond=0)
        minutes_to_boundary = (5 - (rounded_end.minute % 5)) % 5
        target_end = rounded_end + timedelta(minutes=minutes_to_boundary)

        if target_end.time() < time(9, 35) or target_end.time() > session_end:
            return

        if self.current_five_minute_end != target_end:
            self.current_five_minute_end = target_end
            self.expected_minute_end = target_end - timedelta(minutes=4)
            self.five_minute_closes = []

        if minute_end != self.expected_minute_end:
            # A missing minute prevents this five-minute bar from being formed.
            self.five_minute_closes = []
            self.expected_minute_end = minute_end

        self.five_minute_closes.append(bar.close)

        if minute_end != target_end:
            self.expected_minute_end = minute_end + timedelta(minutes=1)
            return

        is_complete = len(self.five_minute_closes) == 5
        five_minute_close = self.five_minute_closes[-1]

        self.current_five_minute_end = None
        self.expected_minute_end = None
        self.five_minute_closes = []

        if not is_complete:
            return

        self._on_five_minute_bar(target_end, five_minute_close, data)

    def _on_five_minute_bar(self, bar_end, close, data: Slice):
        self.fast_closes.append(close)
        self.slow_closes.append(close)

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return

        current_fast = sum(self.fast_closes) / 5.0
        current_slow = sum(self.slow_closes) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if not bullish_cross:
            return

        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        self._try_enter(data)

    def _try_enter(self, data: Slice):
        if self.blocked_entry_date == self.time.date():
            return

        if self._has_option_position() or self._entry_order_is_open():
            return

        chain = data.option_chains.get(self.option_symbol)
        if chain is None:
            self.debug("Entry skipped: no SPY option chain in Slice")
            return

        underlying_price = self.securities[self.spy].price
        if underlying_price <= 0:
            self.debug("Entry skipped: invalid SPY price")
            return

        minimum_expiry = self.time.date() + timedelta(days=7)
        eligible_expiries = sorted({
            contract.expiry.date()
            for contract in chain
            if contract.expiry.date() >= minimum_expiry
        })

        if not eligible_expiries:
            self.debug("Entry skipped: no expiration at least 7 calendar days away")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = underlying_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.expiry.date() == selected_expiry
            and contract.right == OptionRight.CALL
            and contract.strike >= minimum_strike
        ]

        if not candidates:
            self.debug("Entry skipped: no qualifying call at selected expiration")
            return

        contract = sorted(
            candidates,
            key=lambda item: (item.strike, str(item.symbol))
        )[0]

        self.pending_entry_symbol = contract.symbol
        self.entry_ticket = self.market_order(contract.symbol, 1)

    def _check_profit_target(self, data: Slice):
        if not self._has_option_position():
            return

        if self.entry_price is None or self._entry_order_is_open() or self._exit_order_is_open():
            return

        quote = data.quote_bars.get(self.held_contract)
        if quote is None or quote.bid is None or quote.ask is None:
            return

        bid = quote.bid.close
        ask = quote.ask.close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self._submit_option_exit("profit target")

    def _pre_expiry_time_stop(self):
        if not self._has_option_position() or self._exit_order_is_open():
            return

        expiry = self.held_contract.id.date.date()
        try:
            next_open = self.securities[self.spy].exchange.hours.get_next_market_open(
                self.time, False
            )
        except Exception:
            return

        if next_open.date() == expiry:
            self._submit_option_exit("pre-expiration 15:45 time stop")

    def _expiration_safety_exit(self):
        if not self._has_option_position():
            return

        expiry = self.held_contract.id.date.date()
        if self.time.date() >= expiry:
            self.blocked_entry_date = self.time.date()
            if not self._exit_order_is_open():
                self._submit_option_exit("expiration safety exit")

    def _submit_option_exit(self, reason):
        if not self._has_option_position():
            return

        if self._exit_order_is_open():
            return

        quantity = self.portfolio[self.held_contract].quantity
        if quantity == 0:
            return

        self.pending_exit_symbol = self.held_contract
        self.exit_ticket = self.market_order(self.held_contract, -quantity)
        self.debug(f"Exit submitted ({reason}): {self.held_contract}")

    def _liquidate_unexpected_spy_position(self):
        spy_holding = self.portfolio[self.spy]
        if spy_holding.quantity == 0:
            return

        open_orders = self.transactions.get_open_orders(self.spy)
        if any(order.quantity * spy_holding.quantity < 0 for order in open_orders):
            return

        self.debug("Unexpected SPY exercise/assignment position; liquidating")
