        self.entry_submitting_symbol = None

    def ProcessOptionExit(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.HasOpenExitOrder():
            return

        quote = slice.QuoteBars.get(self.held_symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self.CancelOpenExitOrders()
            self.SubmitExit("profit target")

    def ProcessExpirationProtection(self):
        if self.held_symbol is None or self.held_expiry is None:
            return

        today = self.Time.date()

        if today >= self.held_expiry:
            self.no_entry_dates.add(today)
            if not self.HasOpenExitOrder():
                self.SubmitExit("expiration-day protection")
            return

        previous_trading_day = self.PreviousTradingDay(self.held_expiry)
        if today == previous_trading_day and self.Time.time() == time(15, 45):
            if not self.HasOpenExitOrder():
                self.SubmitExit("pre-expiration time stop")

    def SubmitExit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"{self.Time}: Exit submitted for {self.held_symbol} ({reason}).")

    def PreviousTradingDay(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate, False):
            candidate -= timedelta(days=1)

        return candidate

    def FlattenUnexpectedSpyPosition(self):
        spy_quantity = self.Portfolio[self.spy].Quantity

        if spy_quantity == 0:
            self.spy_liquidation_order_id = None
            return

        if self.spy_liquidation_order_id is not None:
            ticket = self.Transactions.GetOrderTicket(self.spy_liquidation_order_id)
            if ticket is not None and ticket.Status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                return

        self.Debug(
            f"{self.Time}: Unexpected SPY equity position detected; liquidating {spy_quantity} shares."
        )
        ticket = self.MarketOrder(self.spy, -spy_quantity)
        self.spy_liquidation_order_id = ticket.OrderId

    def HasOptionHolding(self):
        return (
            self.held_symbol is not None
            and self.Portfolio[self.held_symbol].Quantity != 0
        )

    def HasOpenEntryOrder(self):
        return self.IsOrderOpen(self.entry_order_id)

    def HasOpenExitOrder(self):
        return self.IsOrderOpen(self.exit_order_id)

    def IsOrderOpen(self, order_id):
        if order_id is None:
            return False

        ticket = self.Transactions.GetOrderTicket(order_id)
        if ticket is None:
            return False

        return ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def CancelOpenExitOrders(self):
        if self.exit_order_id is not None and self.IsOrderOpen(self.exit_order_id):
            self.Transactions.CancelOrder(self.exit_order_id)

    def OnOrderEvent(self, order_event):
        is_entry = (
            order_event.OrderId == self.entry_order_id
            or (
                self.entry_order_id is None
                and self.entry_submitting_symbol == order_event.Symbol
            )
        )

        if is_entry:
            if order_event.FillQuantity > 0:
                self.held_symbol = order_event.Symbol
                self.held_expiry = order_event.Symbol.ID.Date.date()
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"{self.Time}: Entered 1 {self.held_symbol} at {self.entry_price:.2f}."
                )

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_order_id = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_order_id = None

            if (
                order_event.Status == OrderStatus.Filled
                and self.held_symbol is not None
                and self.Portfolio[self.held_symbol].Quantity == 0
            ):
                self.Debug(f"{self.Time}: Option exit filled for {self.held_symbol}.")
                self.held_symbol = None
                self.held_expiry = None
                self.entry_price = None

        self.FlattenUnexpectedSpyPosition()
